class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> positions = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) positions.put(inorder[i], i);
        return build(preorder, 0, 0, inorder.length, positions);
    }
    private TreeNode build(int[] preorder, int preStart, int inStart, int size,
                           Map<Integer, Integer> positions) {
        if (size == 0) return null;
        TreeNode root = new TreeNode(preorder[preStart]);
        int leftSize = positions.get(root.val) - inStart;
        // 前序的根之后，先是完整左子树，再是完整右子树。
        root.left = build(preorder, preStart + 1, inStart, leftSize, positions);
        root.right = build(preorder, preStart + leftSize + 1,
                           inStart + leftSize + 1, size - leftSize - 1, positions);
        return root;
    }
}

