class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        positions = {value: i for i, value in enumerate(inorder)}
        def build(pre_start, in_start, size):
            if size == 0:
                return None
            root = TreeNode(preorder[pre_start])
            left_size = positions[root.val] - in_start
            # 用下标限定区间，避免反复切片。
            root.left = build(pre_start + 1, in_start, left_size)
            root.right = build(pre_start + left_size + 1,
                               in_start + left_size + 1, size - left_size - 1)
            return root
        return build(0, 0, len(inorder))
